const defaultConfig={likes:!0,reposts:!0,replies:!0,mentions:!0},refUrl=window.location.href.replace(/#.$/,""),apiUrl="https://webmention.io/api/",imagePlaceholder="data:image/png;base64,";let config={};async function fetchResponse(e){let t={};try{let n=await fetch("https://webmention.io/api/"+e);if(!n.ok)throw Error(`fetchResponse received HTTP status ${n.status}`);return t=n.json()}catch(o){console.error("Request failed:",o.message)}}async function getCounts(e){let t=fetchResponse("count?target="+e);return t}async function getAllMentions(e,t){let n=await fetchResponse(`mentions.jf2?target=${t}&sort-by=published&sort-dir=up&per-page=${e}`);return n?.children}function formatCounts(e){let t=e.type.reply,n=e.type.mention,o=e.type.like,i=e.type.repost,s="";return(o&&config.likes&&(s=`<span>${o} ${o>1?"Likes":"Like"}</span> `),i&&config.reposts&&(s+=`<span>${i} ${i>1?"Reposts":"Repost"}</span> `),t&&config.replies&&(s+=`<span>${t} ${t>1?"Replies":"Reply"}</span> `),n&&config.mentions&&(s+=`<span>${n} ${n>1?"Mentions":"Mention"}</span>`),s)?`<p class="mention-counts">${s}</p>`:""}function getMentions(e,t){let n=e.filter(e=>e["wm-property"]===t);return n}function formatLikes(e,t){let n=getMentions(e,t),o="<ul>";return n.forEach(e=>{let t=e.author.name||e.author.url,n=e.author.photo||imagePlaceholder;o+=`<li><a href="${e.author.url}" title="${t}" rel="nofollow"><img src="${n}"></a></li>`}),`${o}</ul>`}function formatReplies(e,t){let n=getMentions(e,t),o="<ul>";return n.forEach(e=>{let t=e.author.name||e.author.url,n=e.author.photo||imagePlaceholder;o+=`<li><a href="${e.url}" title="${t}" rel="nofollow"><img src="${n}"></a></li>`}),`${o}</ul>`}function formatMentions(e,t){let n=getMentions(e,t),o="<ul>";return n.forEach(e=>{let t=e.author.name||e.author.url,n=e.author.photo||imagePlaceholder;o+=`<li><img src="${n}"> <span class="author-name">${t}:</span> <a href="${e.url}"><span class="reply-text">${e.url}<span></a></li>`}),`${o}</ul>`}window.addEventListener("load",async function(){let e=this.document.getElementById("webmentions");if(!e)return;Object.entries(defaultConfig).forEach(function([t,n]){e.hasAttribute(`data-${t}`)?config[t]="true"===e.getAttribute(`data-${t}`):config[t]=n});let t=await getCounts(refUrl),n=await getAllMentions(t?.count,refUrl),o=formatCounts(t);t.type.like&&config.likes&&(o+=`<div class="likes"><h2>Likes</h2>${formatLikes(n,"like-of")}</div>`),t.type.repost&&config.reposts&&(o+=`<div class="likes"><h2>Reposts</h2>${formatLikes(n,"repost-of")}</div>`),t.type.reply&&config.replies&&(o+=`<div class="replies"><h2>Replies</h2>${formatReplies(n,"in-reply-to")}</div>`),t.type.mention&&config.mentions&&(o+=`<div class="replies"><h2>Mentions</h2>${formatMentions(n,"mention-of")}</div>`),e.innerHTML=o});
